import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.BrO6lPIi.js";const g=JSON.parse('{"title":"端到端测试","description":"本文件面向 AI Helper Chrome 扩展（Manifest V3，版本 2.7.0）的端到端测试体系。","frontmatter":{"title":"端到端测试","description":"本文件面向 AI Helper Chrome 扩展（Manifest V3，版本 2.7.0）的端到端测试体系。"},"headers":[],"relativePath":"测试与质量保证/端到端测试/index.md","filePath":"测试与质量保证/端到端测试/index.md","lastUpdated":null}'),o={name:"测试与质量保证/端到端测试/index.md"};function l(s,e,n,c,h,d){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="端到端测试" tabindex="-1">端到端测试 <a class="header-anchor" href="#端到端测试" aria-label="Permalink to &quot;端到端测试&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js" target="_blank" rel="noreferrer">playwright.config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json" target="_blank" rel="noreferrer">package.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/content-tools.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/content-tools.e2e.spec.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump-interaction.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/message-jump-interaction.e2e.spec.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/message-jump.e2e.spec.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/options-save-bar.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/options-save-bar.e2e.spec.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/iframe-ref.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/iframe-ref.e2e.spec.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与执行策略">性能与执行策略</a></li><li><a href="#视觉回归与-ui-一致性验证">视觉回归与 UI 一致性验证</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录测试脚本示例索引">附录：测试脚本示例索引</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件面向 AI Helper Chrome 扩展（Manifest V3，版本 2.7.0）的端到端测试体系。文档聚焦 Playwright e2e 测试框架的配置与环境搭建、浏览器自动化配置、测试环境准备、测试数据管理、E2E 场景设计、测试执行策略、具体测试脚本示例、视觉回归与 UI 一致性验证，以及测试维护指南。</p><p>本项目采用双进程架构：Chrome 扩展端与独立本地 Agent 端。Agent 端源码修改后必须重启进程，新接口才生效；但当前仓库中的 Playwright e2e 主要覆盖扩展侧内容脚本工具、侧边栏交互、选项页保存按钮栏等前端行为，不直接启动或连接 Agent HTTP/WebSocket 服务。因此，本节 E2E 文档以扩展端真实 Chromium 页面和 content script 工具为主。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>Playwright e2e 测试位于 <code>test/e2e</code>，由根级 <code>playwright.config.js</code> 驱动，并通过 <code>package.json</code> 中脚本统一入口。</p><pre class="mermaid">graph TB
Root[&quot;仓库根目录&quot;] --&gt; PWConfig[&quot;playwright.config.js&quot;]
Root --&gt; Package[&quot;package.json&quot;]
Root --&gt; TestE2E[&quot;test/e2e&quot;]
TestE2E --&gt; Helpers[&quot;helpers/load-module.js&quot;]
TestE2E --&gt; SpecA[&quot;content-tools.e2e.spec.js&quot;]
TestE2E --&gt; SpecB[&quot;demo-product-form.e2e.spec.js&quot;]
TestE2E --&gt; SpecC[&quot;message-jump-interaction.e2e.spec.js&quot;]
TestE2E --&gt; SpecD[&quot;message-jump.e2e.spec.js&quot;]
TestE2E --&gt; SpecE[&quot;options-save-bar.e2e.spec.js&quot;]
TestE2E --&gt; SpecF[&quot;iframe-ref.e2e.spec.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js#L1-L19" target="_blank" rel="noreferrer">playwright.config.js#L1-L19</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L6-L23" target="_blank" rel="noreferrer">package.json#L6-L23</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js#L1-L19" target="_blank" rel="noreferrer">playwright.config.js#L1-L19</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L6-L23" target="_blank" rel="noreferrer">package.json#L6-L23</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><p>Playwright e2e 的核心由三部分构成：</p><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>关键实现位置</th></tr></thead><tbody><tr><td>Playwright 配置</td><td>定义测试目录、并行策略、重试、headless、动作超时、Chromium 设备</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js" target="_blank" rel="noreferrer">playwright.config.js</a></td></tr><tr><td>模块加载器</td><td>使用 esbuild 将 content script 相关模块打包为 IIFE，注入到被测页面并暴露全局调用能力</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js</a></td></tr><tr><td>测试用例集</td><td>覆盖内容工具链路、商品录入 Demo、消息跳转交互、消息跳转布局、选项页保存按钮栏吸附、iframe 跨帧 ref</td><td>各 <code>.e2e.spec.js</code> 文件</td></tr></tbody></table><h3 id="playwright-配置要点" tabindex="-1">Playwright 配置要点 <a class="header-anchor" href="#playwright-配置要点" aria-label="Permalink to &quot;Playwright 配置要点&quot;">​</a></h3><ul><li>测试目录：<code>./test/e2e</code></li><li>并行执行：开启 <code>fullyParallel</code></li><li>CI 模式：<code>forbidOnly</code> 在 CI 下启用，避免误提交 <code>test.only</code></li><li>失败重试：CI 下重试 1 次，本地默认 0 次</li><li>浏览器运行：headless 模式，动作超时 10 秒</li><li>项目：仅 Chromium，使用桌面 Chrome 设备描述</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js#L1-L19" target="_blank" rel="noreferrer">playwright.config.js#L1-L19</a></li></ul><h3 id="模块加载器" tabindex="-1">模块加载器 <a class="header-anchor" href="#模块加载器" aria-label="Permalink to &quot;模块加载器&quot;">​</a></h3><p><code>load-module.js</code> 通过 esbuild 把以下 content script 模块聚合为 IIFE：</p><ul><li><code>src/content/page-utils.js</code></li><li><code>src/content/shadow-dom-utils.js</code></li><li><code>src/content/page-interaction.js</code></li><li><code>src/content/page-extract.js</code></li><li><code>src/content/interaction-tools.js</code></li><li><code>src/shared/page-snapshot-renderer.js</code></li></ul><p>打包结果挂载到 <code>window.__tools</code>，并提供：</p><ul><li><code>getContentBundle()</code>：缓存 bundle，避免重复构建</li><li><code>callTool(page, fnName, ...args)</code>：在 page 上下文调用工具函数</li><li><code>callToolInFrame(page, frameName, fnName, ...args)</code>：在指定 iframe 上下文中调用工具</li></ul><p>该设计使 e2e 测试能在真实 Chromium 中直接验证 content script 的工具链，而不必依赖扩展安装流程。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js#L1-L46" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js#L1-L46</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>Playwright e2e 的执行路径可概括为：</p><pre class="mermaid">sequenceDiagram
participant Dev as &quot;开发者&quot;
participant NPM as &quot;npm test : e2e&quot;
participant PW as &quot;Playwright&quot;
participant Browser as &quot;Chromium&quot;
participant Page as &quot;被测页面&quot;
participant Tools as &quot;window.__tools&quot;
Dev-&gt;&gt;NPM : 运行 npm run test : e2e
NPM-&gt;&gt;PW : playwright test
PW-&gt;&gt;Browser : 启动 headless Chromium
Browser-&gt;&gt;Page : 导航到 file : // 或内置 HTML
Page-&gt;&gt;Tools : addInitScript 注入 IIFE
Page-&gt;&gt;Tools : 调用 query / interact / extract 等工具
Tools--&gt;&gt;Page : 返回 success / content / availableOptions 等
Page--&gt;&gt;PW : expect 断言
PW--&gt;&gt;Dev : 测试结果
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L16-L20" target="_blank" rel="noreferrer">package.json#L16-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js#L4-L18" target="_blank" rel="noreferrer">playwright.config.js#L4-L18</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js#L12-L38" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js#L12-L38</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="内容工具端到端测试" tabindex="-1">内容工具端到端测试 <a class="header-anchor" href="#内容工具端到端测试" aria-label="Permalink to &quot;内容工具端到端测试&quot;">​</a></h3><p><code>content-tools.e2e.spec.js</code> 是内容脚本工具链的代表性 e2e 用例，覆盖：</p><ul><li><code>queryInteractiveElements</code> → <code>interactByRef</code> 完整链路</li><li><code>fillForm</code> 多类型表单填充</li><li><code>selectDropdown</code> 原生 select 选择</li><li><code>clickByText</code> 文本点击</li><li>Shadow DOM 穿透查询与点击</li><li><code>scrollAndCollect</code> 无限滚动收集</li><li><code>extractLinks</code>、<code>pageToJson</code> 链接与表格提取</li><li><code>searchInPage</code> 正则搜索</li><li><code>getIframeContent</code> 同源 iframe 内容获取</li><li><code>queryInteractiveElements</code> 分页、叠加层提升、去重、ref 稳定性</li></ul><p>该用例通过 <code>addInitScript</code> 注入 <code>window.__tools</code>，再使用 <code>callTool</code> 调用工具方法，最后用 Playwright 断言 DOM 状态、返回值字段和交互结果。</p><pre class="mermaid">flowchart TD
Start([&quot;进入用例&quot;]) --&gt; LoadBundle[&quot;加载 content 工具 bundle&quot;]
LoadBundle --&gt; Inject[&quot;addInitScript 注入 window.__tools&quot;]
Inject --&gt; Navigate[&quot;导航到 fixtures 页面&quot;]
Navigate --&gt; Query[&quot;调用 queryInteractiveElements&quot;]
Query --&gt; ValidateQuery{&quot;查询成功？&quot;}
ValidateQuery --&gt; |否| Fail[&quot;断言失败&quot;]
ValidateQuery --&gt; |是| Interact[&quot;调用 interactByRef 或 fillForm/select/click&quot;]
Interact --&gt; AssertDOM[&quot;断言 DOM 值、属性、可见性&quot;]
AssertDOM --&gt; End([&quot;用例结束&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/content-tools.e2e.spec.js#L10-L51" target="_blank" rel="noreferrer">test/e2e/content-tools.e2e.spec.js#L10-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js#L12-L38" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js#L12-L38</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/content-tools.e2e.spec.js#L1-L251" target="_blank" rel="noreferrer">test/e2e/content-tools.e2e.spec.js#L1-L251</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js#L1-L46" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js#L1-L46</a></li></ul><h3 id="商品录入-demo-页面冒烟测试" tabindex="-1">商品录入 Demo 页面冒烟测试 <a class="header-anchor" href="#商品录入-demo-页面冒烟测试" aria-label="Permalink to &quot;商品录入 Demo 页面冒烟测试&quot;">​</a></h3><p><code>demo-product-form.e2e.spec.js</code> 针对演示页面进行冒烟测试，覆盖：</p><ul><li>四步向导流转</li><li>模态框打开、条款勾选、确认提交</li><li>提交后列表追加、回到 Step1</li><li>必填校验阻止下一步并显示错误</li><li>双语切换保持选中值与持久化</li><li>清空列表恢复空态</li><li>叠加层提升到 <code>[打开层]</code>，ref 可操作</li></ul><p>该用例具备“素材缺失自动跳过”机制：若 <code>.resources/demo/form-autofill/product-form.html</code> 不存在，则整组用例 skip，避免克隆仓库时出现无关失败。</p><pre class="mermaid">flowchart TD
CheckDemo[&quot;检查 demo 页面是否存在&quot;] --&gt; HasDemo{&quot;存在？&quot;}
HasDemo --&gt; |否| Skip[&quot;跳过整组用例&quot;]
HasDemo --&gt; |是| RunSuite[&quot;运行商品录入用例&quot;]
RunSuite --&gt; StepFlow[&quot;四步向导填写&quot;]
StepFlow --&gt; Modal[&quot;打开确认模态框&quot;]
Modal --&gt; Terms[&quot;勾选条款并提交&quot;]
Terms --&gt; ListAppend[&quot;列表追加记录&quot;]
ListAppend --&gt; Reset[&quot;重置或清空列表&quot;]
Reset --&gt; OverlayRef[&quot;叠加层 ref 操作&quot;]
OverlayRef --&gt; End([&quot;用例结束&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js#L12-L51" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js#L12-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js#L53-L152" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js#L53-L152</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js#L1-L153" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js#L1-L153</a></li></ul><h3 id="消息跳转交互测试" tabindex="-1">消息跳转交互测试 <a class="header-anchor" href="#消息跳转交互测试" aria-label="Permalink to &quot;消息跳转交互测试&quot;">​</a></h3><p><code>message-jump-interaction.e2e.spec.js</code> 用真实鼠标、键盘事件驱动侧边栏消息跳转把手，覆盖：</p><ul><li>悬停把手展开列表</li><li>鼠标移出自动收起，钉住后移出保持展开</li><li>Tab 键盘可达，↑/↓ 移动焦点</li><li>搜索过滤命中子集，编号仍为全局组序</li><li>中文输入法组合期间不销毁输入框，上屏后才过滤</li><li>Esc 优先清空搜索词，再按一次退钉住/收起</li><li>边界反馈：最后一组继续向下跳时按钮进入 blocked 态</li><li>钉住后手动滚列表去点远处条目，不会被“跟随当前项”拽回顶部</li><li>点击条目后移开鼠标再滚对话，当前项会滚进列表可视区</li></ul><p>该用例通过 esbuild 动态构建 NavKit，并在内存 HTML 中注入真实样式与 DOM，从而验证真实交互而非纯逻辑。</p><pre class="mermaid">sequenceDiagram
participant PW as &quot;Playwright&quot;
participant Page as &quot;内存 HTML 页面&quot;
participant NavKit as &quot;NavKit.initMessageJumpNav&quot;
participant User as &quot;用户交互&quot;
PW-&gt;&gt;Page : setContent(navPageHtml)
Page-&gt;&gt;NavKit : initMessageJumpNav()
User-&gt;&gt;Page : hover 把手
Page--&gt;&gt;PW : 面板 expanded
User-&gt;&gt;Page : click 钉住
User-&gt;&gt;Page : type 搜索词
User-&gt;&gt;Page : press Escape
Page--&gt;&gt;PW : 清词、恢复全部、退钉住、收起
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump-interaction.e2e.spec.js#L22-L41" target="_blank" rel="noreferrer">test/e2e/message-jump-interaction.e2e.spec.js#L22-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump-interaction.e2e.spec.js#L47-L82" target="_blank" rel="noreferrer">test/e2e/message-jump-interaction.e2e.spec.js#L47-L82</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump-interaction.e2e.spec.js#L84-L274" target="_blank" rel="noreferrer">test/e2e/message-jump-interaction.e2e.spec.js#L84-L274</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump-interaction.e2e.spec.js#L1-L274" target="_blank" rel="noreferrer">test/e2e/message-jump-interaction.e2e.spec.js#L1-L274</a></li></ul><h3 id="消息跳转布局与渲染测试" tabindex="-1">消息跳转布局与渲染测试 <a class="header-anchor" href="#消息跳转布局与渲染测试" aria-label="Permalink to &quot;消息跳转布局与渲染测试&quot;">​</a></h3><p><code>message-jump.e2e.spec.js</code> 侧重真实布局与滚动下的消息跳转分组定位，覆盖：</p><ul><li>问答组覆盖每条提问与其后的回答，编号连续</li><li>按编号跳转后反查当前组得到同一编号</li><li>连按上一条/下一条在组间移动并停在边界</li><li>面板为实色表面，条目不折行成单行截断</li><li>长提问恰好两行且由 CSS 画省略号</li><li>折行的第二行与第一行文字左对齐</li><li>当前组条目高亮态样式</li><li>暗色主题下列表同样是实色底</li><li>列表垂直滚动时 Header 固定可见</li><li>面板无显式高度时列表区不得塌成 0</li><li>预览文案折叠空白并按上限截断</li></ul><p>该用例读取真实 <code>theme.css</code> 与 <code>side_panel/styles.css</code>，并使用真实 <code>renderQuestionListHtml</code> 生成面板内容，避免手写副本漂移。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump.e2e.spec.js#L1-L345" target="_blank" rel="noreferrer">test/e2e/message-jump.e2e.spec.js#L1-L345</a></li></ul><h3 id="选项页保存按钮栏吸附测试" tabindex="-1">选项页保存按钮栏吸附测试 <a class="header-anchor" href="#选项页保存按钮栏吸附测试" aria-label="Permalink to &quot;选项页保存按钮栏吸附测试&quot;">​</a></h3><p><code>options-save-bar.e2e.spec.js</code> 验证真实浏览器下保存按钮栏的吸附行为：</p><ul><li>内容超出一屏：按钮栏吸附在视口底部保持可见</li><li>滚到页面底部后释放回文档流</li><li>内容一屏放得下：按钮栏保持在文档流正常位置</li></ul><p>该用例通过 esbuild 打包 <code>src/options/save-bar.js</code>，并注入真实 <code>src/options/styles.css</code>，构造与真实 options 页面一致的层级结构。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/options-save-bar.e2e.spec.js#L1-L88" target="_blank" rel="noreferrer">test/e2e/options-save-bar.e2e.spec.js#L1-L88</a></li></ul><h3 id="iframe-跨帧-ref-测试" tabindex="-1">iframe 跨帧 ref 测试 <a class="header-anchor" href="#iframe-跨帧-ref-测试" aria-label="Permalink to &quot;iframe 跨帧 ref 测试&quot;">​</a></h3><p><code>iframe-ref.e2e.spec.js</code> 验证真实 iframe 环境下跨帧 ref 采集与整体渲染组装，覆盖：</p><ul><li>auto 采集：frame 节点属性与 display:none 剪枝</li><li>none 采集旧入口薄包装</li><li>子帧内采集：frameInfo 来自 srcdoc 文档、loadId 存在</li><li>可见性判定：可见帧 true；display:none 与零尺寸 false</li><li>组装渲染：占位行编号 + 子帧区块缩进 + 隐藏帧移除</li><li>子帧内本地 ref 交互：注册表解析 + type 生效</li></ul><p>该用例复用 <code>load-module.js</code> 提供的 <code>callTool</code> 与 <code>callToolInFrame</code>，确保跨帧工具调用路径正确。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/iframe-ref.e2e.spec.js#L1-L117" target="_blank" rel="noreferrer">test/e2e/iframe-ref.e2e.spec.js#L1-L117</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js#L40-L46" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js#L40-L46</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>e2e 测试对仓库其他部分的依赖如下：</p><pre class="mermaid">graph LR
PWConfig[&quot;playwright.config.js&quot;] --&gt; Specs[&quot;所有 .e2e.spec.js&quot;]
Specs --&gt; LoadModule[&quot;helpers/load-module.js&quot;]
Specs --&gt; ContentModules[&quot;src/content/*&quot;]
Specs --&gt; SharedModules[&quot;src/shared/*&quot;]
Specs --&gt; SidePanelCSS[&quot;src/side_panel/styles.css&quot;]
Specs --&gt; ThemeCSS[&quot;src/shared/theme.css&quot;]
Specs --&gt; OptionsCSS[&quot;src/options/styles.css&quot;]
Specs --&gt; Esbuild[&quot;esbuild&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js#L4-L18" target="_blank" rel="noreferrer">playwright.config.js#L4-L18</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js#L12-L32" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js#L12-L32</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump-interaction.e2e.spec.js#L22-L41" target="_blank" rel="noreferrer">test/e2e/message-jump-interaction.e2e.spec.js#L22-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump.e2e.spec.js#L21-L39" target="_blank" rel="noreferrer">test/e2e/message-jump.e2e.spec.js#L21-L39</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/options-save-bar.e2e.spec.js#L18-L29" target="_blank" rel="noreferrer">test/e2e/options-save-bar.e2e.spec.js#L18-L29</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js#L1-L19" target="_blank" rel="noreferrer">playwright.config.js#L1-L19</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js#L1-L46" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js#L1-L46</a></li></ul><h2 id="性能与执行策略" tabindex="-1">性能与执行策略 <a class="header-anchor" href="#性能与执行策略" aria-label="Permalink to &quot;性能与执行策略&quot;">​</a></h2><h3 id="并行测试" tabindex="-1">并行测试 <a class="header-anchor" href="#并行测试" aria-label="Permalink to &quot;并行测试&quot;">​</a></h3><p>Playwright 配置开启 <code>fullyParallel: true</code>，意味着每个 spec 文件内的用例可在不同 worker 中并行执行。这能显著缩短 CI 时间，但也要求用例之间保持隔离，避免共享全局状态。</p><h3 id="重试机制" tabindex="-1">重试机制 <a class="header-anchor" href="#重试机制" aria-label="Permalink to &quot;重试机制&quot;">​</a></h3><ul><li>本地环境：<code>retries: 0</code></li><li>CI 环境：<code>retries: 1</code></li></ul><p>建议在新增不稳定用例时先定位根因，而不是盲目增加重试次数。对于网络或外部资源依赖的用例，应优先改为本地 fixture 或 mock。</p><h3 id="动作超时" tabindex="-1">动作超时 <a class="header-anchor" href="#动作超时" aria-label="Permalink to &quot;动作超时&quot;">​</a></h3><p><code>actionTimeout: 10000</code> 表示每次 action 最多等待 10 秒。若某个用例频繁超时，应检查：</p><ul><li>是否缺少 <code>waitForSelector</code> 或 <code>waitForFunction</code></li><li>是否动画未结束就断言</li><li>是否 fixture 页面加载过慢</li><li>是否使用了错误的定位器</li></ul><h3 id="调试模式" tabindex="-1">调试模式 <a class="header-anchor" href="#调试模式" aria-label="Permalink to &quot;调试模式&quot;">​</a></h3><p>可通过 <code>npm run test:e2e:headed</code> 启动 headed 模式，便于观察浏览器行为。该命令对应 package.json 中的脚本定义。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js#L4-L12" target="_blank" rel="noreferrer">playwright.config.js#L4-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L16-L20" target="_blank" rel="noreferrer">package.json#L16-L20</a></li></ul><h2 id="视觉回归与-ui-一致性验证" tabindex="-1">视觉回归与 UI 一致性验证 <a class="header-anchor" href="#视觉回归与-ui-一致性验证" aria-label="Permalink to &quot;视觉回归与 UI 一致性验证&quot;">​</a></h2><p>当前仓库的 Playwright e2e 并未使用截图对比类视觉回归库，而是通过以下方式保证 UI 一致性：</p><table tabindex="0"><thead><tr><th>验证方式</th><th>说明</th><th>对应用例</th></tr></thead><tbody><tr><td>真实样式加载</td><td>测试直接读取 <code>theme.css</code> 与 <code>side_panel/styles.css</code>，避免样式漂移</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/message-jump.e2e.spec.js</a></td></tr><tr><td>计算样式断言</td><td>断言背景透明度、textOverflow、lineClamp、visibleLines 等</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/message-jump.e2e.spec.js</a></td></tr><tr><td>主题断言</td><td>断言暗色主题下面板背景与文字颜色</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/message-jump.e2e.spec.js</a></td></tr><tr><td>吸附行为断言</td><td>断言 <code>.floating</code> 类名与视口位置</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/options-save-bar.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/options-save-bar.e2e.spec.js</a></td></tr><tr><td>面板结构断言</td><td>断言面板内部 header、list、item 的滚动行为</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/message-jump.e2e.spec.js</a></td></tr></tbody></table><p>如果需要引入截图对比，建议：</p><ul><li>使用 Playwright 内置 <code>toMatchSnapshot</code></li><li>固定 viewport 尺寸</li><li>固定字体与缩放</li><li>区分 light/dark 主题基线</li><li>将基线图片纳入版本控制</li><li>在 CI 中比较差异并生成报告</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump.e2e.spec.js#L135-L265" target="_blank" rel="noreferrer">test/e2e/message-jump.e2e.spec.js#L135-L265</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/options-save-bar.e2e.spec.js#L50-L87" target="_blank" rel="noreferrer">test/e2e/options-save-bar.e2e.spec.js#L50-L87</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><h3 id="常见问题与处理" tabindex="-1">常见问题与处理 <a class="header-anchor" href="#常见问题与处理" aria-label="Permalink to &quot;常见问题与处理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>可能原因</th><th>处理建议</th></tr></thead><tbody><tr><td>用例报 <code>test.only</code></td><td>本地误提交 <code>test.only</code></td><td>CI 下 <code>forbidOnly</code> 会直接失败；删除 <code>only</code></td></tr><tr><td>用例不稳定</td><td>动画未结束、DOM 未就绪、fixture 加载慢</td><td>增加 <code>waitForSelector</code>、<code>waitForFunction</code>，或使用 <code>expect.poll</code></td></tr><tr><td>content 工具调用失败</td><td>bundle 未注入或全局名不对</td><td>检查 <code>addInitScript</code> 与 <code>window.__tools</code></td></tr><tr><td>iframe 工具调用失败</td><td>未找到目标 frame</td><td>使用 <code>callToolInFrame</code> 并确保 frame name 匹配</td></tr><tr><td>样式断言失败</td><td>主题变量或 CSS 变更</td><td>同步更新测试断言，或修复样式</td></tr><tr><td>中文输入法导致列表重建异常</td><td>composition 期间重建输入框</td><td>参考 <code>message-jump-interaction.e2e.spec.js</code> 的组合事件断言</td></tr><tr><td>吸附行为异常</td><td>视口高度或内容高度变化</td><td>检查 <code>setupPage</code> 中 contentHeight 与 viewportSize</td></tr></tbody></table><h3 id="调试技巧" tabindex="-1">调试技巧 <a class="header-anchor" href="#调试技巧" aria-label="Permalink to &quot;调试技巧&quot;">​</a></h3><ul><li>使用 <code>npm run test:e2e:headed</code> 观察真实浏览器</li><li>在 <code>beforeEach</code> 中打印 <code>page.url()</code> 与关键 DOM 结构</li><li>对复杂交互使用 <code>page.screenshot()</code> 辅助定位</li><li>对异步动画使用 <code>waitForTimeout</code> 或更精确的状态等待</li><li>对 fixture 页面问题，先用浏览器手动复现</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/playwright.config.js#L7-L11" target="_blank" rel="noreferrer">playwright.config.js#L7-L11</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump-interaction.e2e.spec.js#L152-L180" target="_blank" rel="noreferrer">test/e2e/message-jump-interaction.e2e.spec.js#L152-L180</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/options-save-bar.e2e.spec.js#L32-L42" target="_blank" rel="noreferrer">test/e2e/options-save-bar.e2e.spec.js#L32-L42</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>该项目的 Playwright e2e 测试体系围绕真实 Chromium、真实样式与真实 DOM 展开，重点验证内容脚本工具链、侧边栏交互、选项页吸附行为与 iframe 跨帧能力。测试通过 esbuild 动态打包模块、通过 <code>addInitScript</code> 注入工具、通过 fixture 页面模拟业务场景，既避免了安装扩展的复杂度，又保留了足够的真实性。</p><p>未来可扩展的方向包括：</p><ul><li>引入截图对比进行视觉回归</li><li>增加更多跨页面流程验证</li><li>补充 Agent 集成测试（需启动本地 Agent 进程）</li><li>细化性能基准用例</li><li>完善测试数据管理与版本化</li></ul><h2 id="附录-测试脚本示例索引" tabindex="-1">附录：测试脚本示例索引 <a class="header-anchor" href="#附录-测试脚本示例索引" aria-label="Permalink to &quot;附录：测试脚本示例索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>测试目标</th><th>文件路径</th><th>关键能力</th></tr></thead><tbody><tr><td>内容工具链路</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/content-tools.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/content-tools.e2e.spec.js</a></td><td>query、interact、fillForm、select、clickByText、Shadow DOM、scroll_collect、extract、search、iframe_content</td></tr><tr><td>商品录入 Demo</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/demo-product-form.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/demo-product-form.e2e.spec.js</a></td><td>向导流程、模态框、双语、列表、叠加层 ref</td></tr><tr><td>消息跳转交互</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump-interaction.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/message-jump-interaction.e2e.spec.js</a></td><td>hover、click、keyboard、composition、Esc、blocked、pinned</td></tr><tr><td>消息跳转布局</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/message-jump.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/message-jump.e2e.spec.js</a></td><td>分组定位、两行截断、省略号、高亮、暗色主题、滚动</td></tr><tr><td>保存按钮栏吸附</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/options-save-bar.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/options-save-bar.e2e.spec.js</a></td><td>floating、视口底部、文档流释放</td></tr><tr><td>iframe 跨帧 ref</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/iframe-ref.e2e.spec.js" target="_blank" rel="noreferrer">test/e2e/iframe-ref.e2e.spec.js</a></td><td>auto/none 采集、frameInfo、可见性、渲染组装</td></tr><tr><td>模块加载器</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/helpers/load-module.js" target="_blank" rel="noreferrer">test/e2e/helpers/load-module.js</a></td><td>getContentBundle、callTool、callToolInFrame</td></tr></tbody></table>`,120)])])}const u=t(o,[["render",l]]);export{g as __pageData,u as default};
